\section{Introduction}

\subsection{Normalized $q$-series and their obstruction}

Throughout, $\CC((q))$ denotes the field of formal Laurent series in $q$ over $\CC$: sums
$\sum_{n \in \ZZ} f_n q^n$ with support bounded below. We write $\co{n}f = f_n$.

\begin{definition}[Normalized series]
A Laurent series $f \in \CC((q))$ is \emph{normalized} if
\[
  \co{-1}f = 1 \quad\text{and}\quad \co{n}f = 0 \text{ for all } n < -1,
\]
equivalently $f = q^{-1} + a_0 + a_1 q + a_2q^2 + \cdots$. Write $\Norm$ for the set of normalized
series.
\end{definition}

This is the standard shape of a Hauptmodul: the $q$-expansion of a generator of the function field
of a genus-zero modular curve, with polar part exactly $q^{-1}$. The McKay--Thompson series of
Monstrous Moonshine are normalized in this sense, with vanishing constant term.

Normalized series are not closed under multiplication. Every normalized series has order $-1$
(order $=$ the least $n$ with $\co{n}f \neq 0$), and orders add in an integral domain.

\begin{proposition}[Pole-order obstruction]\label{prop:obstruction}
If $f$ and $g$ are normalized then $fg$ is never normalized.
\end{proposition}

\begin{proof}
$fg$ has order $(-1) + (-1) = -2 \neq -1$, whereas every normalized series has order $-1$.
\end{proof}

\begin{theorem}[Uniqueness of the correction]\label{thm:unique-correction}
Let $f,g$ be normalized and $m \in \NN$. Then $q^m fg$ is normalized if and only if $m = 1$.
\end{theorem}

\begin{proof}
Orders add: $q^mfg$ has order $m-2$, and normalization forces order $-1$, i.e.\ $m=1$. Conversely
$m=1$ works by Theorem~\ref{thm:closure}.
\end{proof}

\begin{definition}[Corrected product]
For $f,g \in \CC((q))$ set $f \star g = q\,f\,g$.
\end{definition}

\subsection{Results}
The paper answers three questions: whether $\star$ is an algebraic structure (Section~2: it is a
commutative group isomorphic to the one-units); what separates the $\star$-orbits (Sections~3--4:
an infinite tower of invariants with depth as the first orbit invariant); and how the higher
invariants grow (Section~5: an exact finite binomial law). Section~6 applies the theory to
moonshine coefficients, Section~7 records algorithms, and Sections~8--9 discuss and extend.

\section{The corrected product is a commutative group law}

\subsection{One-unit coordinates}

\begin{definition}[One-units]
A power series $u \in \CC[[q]]$ is a \emph{one-unit} if $u(0) = 1$. Write
$\mathcal{U} = 1 + q\CC[[q]]$.
\end{definition}

$\mathcal{U}$ is a commutative group under multiplication: constant terms multiply, and a power
series with unit constant term is invertible in $\CC[[q]]$ with inverse again a one-unit.

\begin{theorem}[Coordinates for normalized series]\label{thm:coords}
A Laurent series $f$ is normalized if and only if $f = q^{-1}u$ for a unique one-unit $u$;
explicitly $u = qf$.
\end{theorem}

\begin{proof}
If $u$ is a one-unit then $\co{n}(q^{-1}u) = \co{n+1}u$, which vanishes for $n < -1$ and equals
$u(0) = 1$ at $n = -1$; so $q^{-1}u$ is normalized. Conversely if $f$ is normalized then $qf$ has
support in $\NN$, hence is a power series, with constant term $\co{-1}f = 1$. Uniqueness is clear
since $u \mapsto q^{-1}u$ is injective.
\end{proof}

We record the coefficient dictionary $\co{k}u = \co{k-1}f$ for $k \geq 0$.

\subsection{Closure and the group law}

\begin{theorem}[Closure]\label{thm:closure}
If $f,g$ are normalized then so is $f\star g = qfg$.
\end{theorem}

\begin{proof}
Write $f = q^{-1}u$, $g = q^{-1}v$ with $u,v$ one-units. Then
$q(q^{-1}u)(q^{-1}v) = (qq^{-1})q^{-1}(uv) = q^{-1}(uv)$, and $uv$ is a one-unit; apply
Theorem~\ref{thm:coords}.
\end{proof}

The same computation shows that \emph{in one-unit coordinates the corrected product is ordinary
multiplication}.

\begin{theorem}[Closure under corrected inversion]
If $f$ is normalized then so is $q^{-2}f^{-1}$, the inverse being taken in $\CC((q))$.
\end{theorem}

\begin{proof}
With $f = q^{-1}u$ one has $f^{-1} = qu^{-1}$, since $(q^{-1}u)(qu^{-1}) = 1$. Hence
$q^{-2}f^{-1} = q^{-1}u^{-1}$ with $u^{-1}$ a one-unit.
\end{proof}

\begin{theorem}[Group structure]\label{thm:group}
The set $\Norm$ with $f \star g = qfg$, identity $e = q^{-1}$ and inversion
$f \mapsto q^{-2}f^{-1}$ is a commutative group.
\end{theorem}

\begin{proof}
Associativity and commutativity: $(f\star g)\star h = q^2fgh = f \star (g\star h)$. Unit:
$q^{-1}\star f = qq^{-1}f = f$. Inverse: $(q^{-2}f^{-1})\star f = qq^{-2}f^{-1}f = q^{-1}$.
Closure of each operation was proved above.
\end{proof}

\begin{theorem}[Structure theorem]\label{thm:structure}
The map $\Phi:\Norm \to \mathcal{U}$, $\Phi(f) = qf$, is an isomorphism of commutative groups
$(\Norm,\star) \xrightarrow{\sim} (\mathcal{U},\cdot)$ with inverse $u \mapsto q^{-1}u$.
\end{theorem}

\begin{proof}
Bijectivity is Theorem~\ref{thm:coords}; multiplicativity is $q(f\star g) = (qf)(qg)$.
\end{proof}

\begin{remark}
The identity element $q^{-1}$ is not distinguished by anything intrinsic to $\Norm$; the honest
statement is that $\Norm$ is a torsor under $\mathcal{U}$, which becomes a group once $q^{-1}$ is
nominated as origin.
\end{remark}

\begin{proposition}[Shape of an iterate]\label{prop:iterate}
For $f$ normalized and $n \geq 1$ we have $f^{\star n} = q^{\,n-1}f^{\,n}$; more generally
$f_1 \star \cdots \star f_N = q^{\,N-1}f_1\cdots f_N$.
\end{proposition}

\begin{proof}
Apply $\Phi$: $\Phi(f^{\star n}) = (qf)^n$, and divide by $q$.
\end{proof}

In particular the corrected product of $194$ normalized series --- one per conjugacy class of the
Monster --- is $q^{193}$ times their ordinary product.

\section{The first invariant}

\begin{definition}
For $f = q^{-1} + a_0 + a_1q + \cdots$ normalized, write $a_0(f) = \co{0}f$.
\end{definition}

\begin{theorem}[Additivity and linear growth]\label{thm:a0}
For all normalized $f,g$ we have $a_0(f\star g) = a_0(f) + a_0(g)$, $a_0(q^{-1}) = 0$ and
$a_0(f^{\star n}) = n\,a_0(f)$. Hence $a_0 : (\Norm,\star)\to(\CC,+)$ is a surjective group
homomorphism.
\end{theorem}

\begin{proof}
In one-unit coordinates $a_0(f) = \co{1}(qf)$, and for one-units
$\co{1}(uv) = u(0)\co{1}v + \co{1}u\,v(0) = \co{1}u + \co{1}v$. Surjectivity: $q^{-1}(1+zq)
= q^{-1}+z$. Linear growth is induction on $n$.
\end{proof}

\begin{proposition}[Incompleteness]
The series $f = q^{-1}+q$ satisfies $f \neq q^{-1}$ and $a_0(f) = 0$; so $a_0$ is not injective,
and the whole orbit of $f$ is invisible to it.
\end{proposition}

\section{The depth filtration and the graded invariants}

\begin{definition}[Level invariants and depth]
For $f$ normalized with $u = qf$ and $k \geq 0$ put $c_k(f) = \co{k}u = \co{k-1}f$; so
$c_0(f) = 1$ and $c_1(f) = a_0(f)$. For $k \geq 1$ let
\[
  \Deep_k = \{\, f \in \Norm : c_i(f) = 0 \text{ for } 1 \le i < k \,\}
\]
be the set of \emph{$k$-deep} series. The \emph{depth} of $f \neq q^{-1}$ is the least $k \geq 1$
with $c_k(f) \neq 0$.
\end{definition}

Say a power series $w$ has \emph{low vanishing at $k$} if $\co{i}w = 0$ for $0 < i < k$.

\begin{lemma}[Below the threshold]\label{lem:below}
If $u$ has low vanishing at $k$ then $\co{m}(ub) = u(0)\co{m}b$ for all $m < k$ and all
$b \in \CC[[q]]$.
\end{lemma}

\begin{proof}
In $\co{m}(ub) = \sum_{i+j=m}\co{i}u\,\co{j}b$ each term with $0 < i \le m < k$ vanishes.
\end{proof}

\begin{lemma}[Additivity at the threshold]\label{lem:threshold}
If $u,v$ both have low vanishing at $k \geq 1$ then
$\co{k}(uv) = u(0)\co{k}v + \co{k}u\,v(0)$, and $uv$ again has low vanishing at $k$. For one-units
this reads $\co{k}(uv) = \co{k}u + \co{k}v$.
\end{lemma}

\begin{proof}
In $\co{k}(uv) = \sum_{i+j=k}\co{i}u\,\co{j}v$ every term with $0<i<k$ (hence $0<j<k$) vanishes,
leaving the two extreme terms; low vanishing of $uv$ is Lemma~\ref{lem:below}.
\end{proof}

\begin{lemma}[Inversion at the threshold]\label{lem:inv}
If $u$ is a one-unit with low vanishing at $k \geq 1$ then $u^{-1}$ is a one-unit with low
vanishing at $k$ and $\co{k}(u^{-1}) = -\co{k}u$.
\end{lemma}

\begin{proof}
Apply Lemma~\ref{lem:below} to $uu^{-1} = 1$, then Lemma~\ref{lem:threshold} to the same identity
at level $k$.
\end{proof}

\begin{theorem}[The tower]\label{thm:tower}
For $k \geq 1$, $\Deep_k$ is a subgroup of $(\Norm,\star)$ and
$\Norm = \Deep_1 \supseteq \Deep_2 \supseteq \cdots$. On $\Deep_k$ the level-$k$ invariant is a
surjective group homomorphism $c_k : (\Deep_k,\star) \twoheadrightarrow (\CC,+)$ whose kernel is
exactly $\Deep_{k+1}$.
\end{theorem}

\begin{proof}
Subgroup and homomorphism: Lemmas~\ref{lem:threshold} and~\ref{lem:inv} in one-unit coordinates.
Surjectivity: $u = 1 + zq^k$ is $k$-deep with $c_k = z$. Kernel: by definition a $k$-deep series is
$(k+1)$-deep iff $c_k$ vanishes on it.
\end{proof}

\begin{corollary}[All graded pieces are $(\CC,+)$]\label{cor:graded}
$\Deep_k/\Deep_{k+1} \cong (\CC,+)$ for every $k \geq 1$; in particular any two graded pieces are
isomorphic, so no invariant intrinsic to a single piece can distinguish levels.
\end{corollary}

\begin{theorem}[Strictness and separatedness]
For every $k \geq 1$ the inclusion $\Deep_{k+1}\subsetneq \Deep_k$ is strict, and
$\bigcap_{k\ge1}\Deep_k = \{q^{-1}\}$.
\end{theorem}

\begin{proof}
Strictness: the series with coordinate $1+q^k$ is $k$-deep with $c_k = 1$. Separatedness: if all
$c_k$ vanish for $k \geq 1$ then $qf = 1$.
\end{proof}

\begin{theorem}[Completeness and freeness]\label{thm:complete}
The map $C : \Norm \to \CC^{\NN}$, $C(f) = (c_1(f),c_2(f),\dots)$, is a bijection.
\end{theorem}

\begin{proof}
Injectivity: the invariants determine all coefficients of $qf$, whose constant term is $1$.
Surjectivity: $q^{-1}(1+\sum_{k\ge1}z_kq^k)$ realizes any prescribed sequence.
\end{proof}

\begin{remark}
$C$ is not a group homomorphism: if $f$ has coordinate $1+q$ then $f\star f$ has coordinate
$1+2q+q^2$, so $c_2(f\star f) = 1$ while $c_2(f)+c_2(f) = 0$. Additivity at level $k$ holds only
after restricting to $\Deep_k$.
\end{remark}

\subsection{Rigidity}

\begin{theorem}[Linear growth at the depth]\label{thm:linear}
If $f \in \Deep_k$ with $k \geq 1$ then $c_k(f^{\star n}) = n\,c_k(f)$ for all $n \geq 0$.
\end{theorem}

\begin{proof}
Induction on $n$ using Lemma~\ref{lem:threshold} and closure of $\Deep_k$ under $\star$.
\end{proof}

\begin{theorem}[Torsion-freeness]\label{thm:torsionfree}
If $f^{\star n} = q^{-1}$ for some $n \geq 1$ then $f = q^{-1}$; hence every non-trivial orbit is
infinite cyclic.
\end{theorem}

\begin{proof}
If $f \neq q^{-1}$, let $k$ be its depth and $c = c_k(f) \neq 0$. Then
$0 = c_k(f^{\star n}) = nc \neq 0$ in $\CC$, a contradiction.
\end{proof}

\begin{theorem}[Unique divisibility]\label{thm:divisible}
For every normalized $f$ and every $n \geq 1$ there is a unique normalized $g$ with
$g^{\star n} = f$. Hence $(\Norm,\star)$ is a torsion-free divisible abelian group, i.e.\ a
$\QQ$-vector space, and every power map is a bijection.
\end{theorem}

\begin{proof}
Uniqueness follows from Theorem~\ref{thm:torsionfree}. Existence: put $u = qf$ and $w = u-1$, which
has zero constant term, so substitution of $w$ into a formal power series is defined
coefficientwise. Substituting $w$ into $(1+X)^{1/n} = \sum_d \binom{1/n}{d}X^d$ gives $v_0$ with
$v_0^n = u$; rescaling by the inverse of its constant term (an $n$-th root of unity) gives a
one-unit $v$ with $v^n = u$, and $g = q^{-1}v$.
\end{proof}

\begin{definition}[Complex corrected powers]
For $f$ normalized with $u = qf$, $w = u-1$ and $r \in \CC$, set
$f^{\star r} = q^{-1}\bigl((1+X)^r|_{X=w}\bigr)$ where $(1+X)^r = \sum_{d\ge0}\binom{r}{d}X^d$.
\end{definition}

\begin{theorem}[One-parameter subgroups]\label{thm:oneparam}
For every normalized $f$: (i) $f^{\star(r+s)} = f^{\star r}\star f^{\star s}$;
(ii) $f^{\star n}$ agrees with the $n$-fold corrected product for $n \in \NN$;
(iii) $f^{\star0} = q^{-1}$ and $f^{\star1} = f$;
(iv) if $f$ is $k$-deep then $c_k(f^{\star r}) = r\,c_k(f)$;
(v) if $f \neq q^{-1}$ then $r \mapsto f^{\star r}$ is injective.
\end{theorem}

\begin{proof}
(i) transports $(1+X)^{r+s} = (1+X)^r(1+X)^s$ through substitution, a ring homomorphism on series
with zero constant term; (ii) is $(1+X)^n$; (iv): in
$\sum_d\binom{r}{d}w^d$ the term $d=0$ contributes nothing at level $k \geq 1$, the term $d=1$
contributes $r\co{k}w = r\,c_k(f)$, and each $d\ge2$ contributes $0$ since $w^d$ has order at least
$dk > k$; (v) follows from (iv).
\end{proof}

\section{The exact binomial law above the depth}

\begin{theorem}[Exact finite binomial expansion]\label{thm:binomial}
Let $u$ be a one-unit with low vanishing at $k \geq 1$ and put $w = u-1$, so $w$ has order at
least $k$. Then for all $m,n \geq 0$
\[
  \co{m}\bigl(u^n\bigr) \;=\; \sum_{d=0}^{\lfloor m/k\rfloor}\binom{n}{d}\,\co{m}\bigl(w^d\bigr),
\]
a finite sum whose range and weights are independent of $n$.
\end{theorem}

\begin{proof}
By the binomial theorem $u^n = \sum_{d=0}^n \binom{n}{d}w^d$, so
$\co{m}u^n = \sum_{d=0}^{n}\binom{n}{d}\co{m}w^d$. Extend both sums to a common range
$0 \le d < N$. The added terms vanish: for $d>n$ because $\binom{n}{d} = 0$; for
$d > \lfloor m/k\rfloor$ because $w^d$ has order at least $dk > m$. (That orders add is proved by
induction on $d$ from the convolution formula.) The two extensions coincide.
\end{proof}

Write $\omega_d(f,m) = \co{m}\bigl((qf-1)^d\bigr)$ for the \emph{binomial weights}.

\begin{theorem}[Polynomial growth of every orbit invariant]\label{thm:polygrowth}
Let $f$ be $k$-deep, $k \geq 1$. Then for every level $m$ and every $n \geq 0$
\[
  c_m\bigl(f^{\star n}\bigr) = \sum_{d=0}^{\lfloor m/k\rfloor}\binom{n}{d}\,\omega_d(f,m),
\]
so the level-$m$ orbit invariant is a polynomial in $n$ of degree at most $\lfloor m/k\rfloor$.
\end{theorem}

Two special cases recover earlier results: for $0<m<k$ the sum is $0$, and for $m=k$ it is
$n\,c_k(f)$, i.e.\ Theorem~\ref{thm:linear}.

\begin{lemma}[Top weight]\label{lem:top}
If $w$ has order at least $k$ then $\co{jk}(w^j) = (\co{k}w)^j$ for all $j \geq 0$.
\end{lemma}

\begin{proof}
Induction on $j$: in $\co{(j+1)k}(w^jw) = \sum_{p+s=(j+1)k}\co{p}(w^j)\co{s}w$, terms with $s<k$
die because $w$ has order $\geq k$ and terms with $p<jk$ die because $w^j$ has order $\geq jk$;
only $(p,s) = (jk,k)$ survives.
\end{proof}

\begin{theorem}[Binomial growth law]\label{thm:growthlaw}
Let $f$ be $k$-deep with depth invariant $c = c_k(f)$. Then for all $j,n \geq 0$
\[
  c_{jk}\bigl(f^{\star n}\bigr) = \binom{n}{j}c^{\,j} + \sum_{d<j}\binom{n}{d}\,\omega_d(f,jk),
\]
so the degree of $n \mapsto c_{jk}(f^{\star n})$ is exactly $j$ whenever $c \neq 0$.
\end{theorem}

\begin{proof}
Theorem~\ref{thm:polygrowth} at $m = jk$, with $\omega_j(f,jk) = c^j$ by Lemma~\ref{lem:top}.
\end{proof}

\begin{corollary}[Quadratic law at twice the depth]\label{cor:quadratic}
For $f$ $k$-deep, $c_{2k}(f^{\star n}) = n\,c_{2k}(f) + \binom{n}{2}c_k(f)^2$.
\end{corollary}

\begin{proof}
The case $j=2$ of Theorem~\ref{thm:growthlaw}. Directly: for one-units $a,b$ with low vanishing at
$k$ one has the Newton splitting $\co{2k}(ab) = \co{2k}a + \co{2k}b + \co{k}a\,\co{k}b$, since the
only surviving antidiagonal terms are $(0,2k)$, $(k,k)$, $(2k,0)$; induction on $n$ then produces
$\binom{n+1}{2} = \binom{n}{2}+n$.
\end{proof}

\begin{theorem}[Finite determination]\label{thm:finitedet}
Let $f,g$ both be $k$-deep and fix a level $m$. If $c_m(f^{\star n}) = c_m(g^{\star n})$ for all
$n \leq \lfloor m/k\rfloor$, then the same holds for every $n \geq 0$.
\end{theorem}

\begin{proof}
Both sides are given by Theorem~\ref{thm:polygrowth} with weight vectors supported on
$d \le \lfloor m/k\rfloor$. By strong induction on $j$, evaluating at $n = j$ and using
$\binom{j}{d} = 0$ for $d>j$ and $\binom{j}{j} = 1$ gives
$\sum_{d<j}\binom{j}{d}\omega_d(f,m) + \omega_j(f,m) = \sum_{d<j}\binom{j}{d}\omega_d(g,m) +
\omega_j(g,m)$; the sums agree by induction, so $\omega_j(f,m) = \omega_j(g,m)$. Equal weight
vectors give equal invariants for all $n$.
\end{proof}

\begin{theorem}[Depth is constant along orbits]\label{thm:depthinvariant}
Let $f$ be $k$-deep, $k \geq 1$, and $n \neq 0$. Then $f^{\star n} \in \Deep_{k+1}$ if and only if
$f \in \Deep_{k+1}$. Hence $f$ and $f^{\star n}$ have the same depth, and the depth is the first
invariant distinguishing $\star$-orbits.
\end{theorem}

\begin{proof}
Both lie in $\Deep_k$ and $c_k(f^{\star n}) = n\,c_k(f)$ with $n \neq 0$ in $\CC$, so one vanishes
iff the other does; apply Theorem~\ref{thm:tower}.
\end{proof}

\section{An application: iterating moonshine}

The McKay--Thompson series of Monstrous Moonshine are normalized with vanishing constant term; the
class $1\mathrm{A}$ series is
\[
  J = q^{-1} + 196884\,q + 21493760\,q^2 + 864299970\,q^3 + \cdots,
\]
so $c_1(J) = 0$: $J$ is $2$-deep with depth invariant $c_2(J) = 196884$.

\begin{theorem}[Linear regime]
For a normalized series $T$ with $c_1(T) = 0$ and every $n \geq 0$, $c_2(T^{\star n}) = n\,c_2(T)$.
For $J$: the coefficient of $q$ in $q^{\,n-1}J^{\,n}$ is exactly $196884\,n$; for $n=2$ it is
$393768$.
\end{theorem}

\begin{theorem}[Quadratic regime]
With $T$ as above, $c_4(T^{\star n}) = n\,c_4(T) + \binom{n}{2}c_2(T)^2$. For $J$: the coefficient
of $q^3$ in $q^{\,n-1}J^{\,n}$ is $864299970\,n + \binom{n}{2}196884^2$, which at $n=2$ equals
$1728599940 + 38763309456 = 40491909396$.
\end{theorem}

\begin{proof}
Theorem~\ref{thm:linear} and Corollary~\ref{cor:quadratic} with $k=2$, using
$c_k(T) = \co{k-1}T$.
\end{proof}

The number $196884^2$ is structural: it is the top binomial weight of Lemma~\ref{lem:top}, the
square of the depth invariant. At level $2j$ the coefficient of $q^{2j-1}$ in $J^{\star n}$ is a
polynomial in $n$ of degree exactly $j$ with leading binomial term $\binom{n}{j}196884^j$, and by
Theorem~\ref{thm:finitedet} it is determined by the iterates $n = 0,\dots,j$.

\section{Algorithms}

All computations use truncated one-unit coordinates $u = qf \bmod q^{M+1}$.

\medskip\noindent\textbf{A. Corrected product and inverse.} The corrected product is the truncated
Cauchy product of one-units ($O(M^2)$); the corrected inverse is the triangular recursion
$v_0 = 1$, $v_m = -\sum_{i=1}^m u_iv_{m-i}$ ($O(M^2)$). Correctness is
Theorem~\ref{thm:structure}.

\medskip\noindent\textbf{B. Orbit invariants by binomial expansion.} For $k$-deep $f$ and level
$m$, compute $w = qf-1$, the powers $w^d$ for $d \le \lfloor m/k\rfloor$, and the weights
$\omega_d = \co{m}w^d$; then $c_m(f^{\star n}) = \sum_d \binom{n}{d}\omega_d$ evaluates the
invariant for \emph{any} $n$ in $O(\lfloor m/k\rfloor)$ operations after an
$O((m/k)M^2)$ precomputation, with no dependence on $n$.

\medskip\noindent\textbf{C. Corrected roots and complex powers.} For $f$ and $r \in \CC$, evaluate
$\sum_{d \le M}\binom{r}{d}(qf-1)^d$ truncated at $q^M$; with $r = 1/n$ this is the unique
$\star$-root of Theorem~\ref{thm:divisible}, computed without root-finding.

\medskip\noindent An application of B is orbit fingerprinting: to test whether $g = f^{\star n}$
for unknown $n$, compare depths (Theorem~\ref{thm:depthinvariant}), read the candidate
$n = c_k(g)/c_k(f)$ from the linear law, and verify at higher levels by polynomial identity checks.

\section{Discussion}

\textbf{Obstruction as structure.} A closure failure, quantified exactly, becomes an algebraic
structure: the failure is one unit of pole order per additional factor, the repair $q^{m-1}$ is
unique (Theorem~\ref{thm:unique-correction}), and the repaired operation is a commutative group
law with a canonical identification (Theorem~\ref{thm:structure}). The correct global statement is
torsorial.

\textbf{Why the invariants behave so well.} All the rigidity traces back to the fact that the
one-unit group is pro-unipotent, the inverse limit of the unipotent quotients
$(1+q\CC[[q]])/(1+q^k\CC[[q]])$, in characteristic zero. Theorem~\ref{thm:oneparam} makes this
concrete without Lie theory, and Theorem~\ref{thm:binomial} says the flow's coefficient functions
are polynomial because the substituted variable is nilpotent to any finite order.

\textbf{What the tower sees.} All graded pieces are isomorphic (Corollary~\ref{cor:graded}) and the
invariant system is free and complete but non-additive (Theorem~\ref{thm:complete}); the resolution
is that depth --- a positional datum in the tower --- is the first genuine orbit invariant
(Theorem~\ref{thm:depthinvariant}).

\textbf{Limits.} These are statements about formal Laurent series over $\CC$. Nothing asserts that
$J^{\star n}$ is modular for $n \geq 2$. Integrality is preserved: if $f,g$ have integer
coefficients then so does $qfg$.

\section{Future directions}

\subsection{Decidability of corrected-product orbit membership}
Finite determination says the level-$m$ invariant of an orbit is a polynomial of degree at most
$\lfloor m/k\rfloor$ in the iteration count. \emph{Conjecture}: for normalized series with
coefficients in a fixed number field, the question ``is $g$ an iterate $f^{\star n}$ of $f$?'' is
decidable, and a witness $n$ --- if one exists --- is bounded by an explicit function of the depth
$k$ and the first level $m$ at which $f$ and $g$ differ.

The key insight is that the exact binomial expansion converts the a priori infinite search over $n$
into a single polynomial equation $\sum_{d \le m/k}c_d\binom{n}{d} = c_m(g)$ with $n$-independent
coefficients; a non-constant polynomial has at most $\lfloor m/k\rfloor$ roots, so either the
level-$m$ equation pins $n$ down to a finite list, or that level carries no information and one
passes to the next, which by strictness of the filtration is a strictly smaller stage.

\subsection{Further lines}
\begin{itemize}
  \item \emph{Integral and $p$-adic structure.} The corrected product preserves $\ZZ$-coefficients,
  but the integral sub-monoid is not divisible. Which integral series have integral $\star$-roots?
  \item \emph{Arithmetic of the weights.} For $J$ the top weights at level $2j$ are $196884^j$; are
  the lower weights uniformly expressible in the moonshine coefficients?
  \item \emph{Other obstruction repairs.} Polar part $q^{-N}$, or leading coefficient
  $\lambda \neq 1$, give corrected products $q^Nfg$ and rescalings; which structure theorems
  survive, and does uniqueness of the monomial repair persist multivariately?
  \item \emph{Finite-level truncations.} The quotients $\Norm/\Deep_k$ are finite-dimensional
  unipotent groups; uniformity in $k$ would give effective bounds for the decidability question.
\end{itemize}

